<?php require 'config.php';require_role('volunteer','organisasi');check_csrf();$u=user();
if($_SERVER['REQUEST_METHOD']==='POST'){
if($u['role']==='volunteer'){db()->prepare('UPDATE volunteers SET domisili=?,skill=?,minat=?,bio=? WHERE user_id=?')->execute([post('domisili'),post('skill'),post('minat'),post('bio'),$u['user_id']]);}
else{db()->prepare('UPDATE organizations SET nama_organisasi=?,deskripsi=?,alamat=? WHERE user_id=?')->execute([post('nama_organisasi'),post('deskripsi'),post('alamat'),$u['user_id']]);}
db()->prepare('UPDATE users SET nama=? WHERE user_id=?')->execute([post('nama'),$u['user_id']]);$_SESSION['user']['nama']=post('nama');flash('success','Profil berhasil diperbarui.');redirect('profile.php');
}
if($u['role']==='volunteer'){$s=db()->prepare('SELECT * FROM volunteers WHERE user_id=?');$s->execute([$u['user_id']]);$p=$s->fetch();}else{$s=db()->prepare('SELECT * FROM organizations WHERE user_id=?');$s->execute([$u['user_id']]);$p=$s->fetch();}
layout_start('Profil');?><div class="page-heading"><span class="eyebrow">AKUN SAYA</span><h1>Pengaturan profil</h1><p class="muted">Pastikan informasi profilmu selalu terbaru.</p></div><form class="form-card wide" method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Nama penanggung jawab / nama akun</label><input name="nama" value="<?=e($u['nama'])?>" required><?php if($u['role']==='volunteer'):?><label>Domisili</label><input name="domisili" value="<?=e($p['domisili'])?>"><label>Skill</label><textarea name="skill"><?=e($p['skill'])?></textarea><label>Minat</label><textarea name="minat"><?=e($p['minat'])?></textarea><label>Bio</label><textarea name="bio"><?=e($p['bio'])?></textarea><?php else:?><label>Nama organisasi</label><input name="nama_organisasi" value="<?=e($p['nama_organisasi'])?>"><label>Alamat</label><input name="alamat" value="<?=e($p['alamat'])?>"><label>Deskripsi</label><textarea name="deskripsi"><?=e($p['deskripsi'])?></textarea><p>Status verifikasi: <?=badge($p['status_verifikasi'])?></p><?php endif;?><button class="btn btn-primary">Simpan perubahan</button></form><?php layout_end(); ?>